import { createContext, useContext, useReducer } from "react";
import { editorReducer, initial } from "./editor-reducer.js";

const EditorState = createContext(null);
const EditorDispatch = createContext(null);   // stable: dispatch never changes.

export function CourseEditorProvider({ children }) {
  const [state, dispatch] = useReducer(editorReducer, initial);
  return (
    <EditorDispatch.Provider value={dispatch}>
      <EditorState.Provider value={state}>{children}</EditorState.Provider>
    </EditorDispatch.Provider>
  );
}

export function useEditorState() {
  const value = useContext(EditorState);
  if (value === null) throw new Error("useEditorState must be used inside CourseEditorProvider");
  return value;
}
export function useEditorDispatch() {
  const value = useContext(EditorDispatch);
  if (value === null) throw new Error("useEditorDispatch must be used inside CourseEditorProvider");
  return value;
}

// Page: only the editor subtree is wrapped.
<CourseEditorProvider>
  <Sidebar /> <LessonForm /> <Preview />
</CourseEditorProvider>
